-- Legacy tables removed from the factory database on 2026-08-10.
-- All were EMPTY (verified by count(*)), referenced by no code in apps/ or
-- packages/, declared in no migration or schema.sql, and depended on by no
-- view. They are remnants of the pre-per-tenant-database architecture.
-- Kept for reference so the removal is reversible.

-- audit_log: id uuid NOT NULL, tenant_id uuid NOT NULL, user_id uuid, action text NOT NULL, entity_type text, entity_id uuid, old_data jsonb, new_data jsonb, ip_address text, created_at timestamp with time zone
-- bids: id uuid NOT NULL, tenant_id uuid NOT NULL, job_id uuid, contact_id uuid, title text NOT NULL, status text, due_date date, submitted_at timestamp with time zone, amount numeric(12,2), notes text, created_by uuid, created_at timestamp with time zone, updated_at timestamp with time zone
